const fs = require('fs');
const path = require('path');
const file = path.join(__dirname, 'command-center.html');
let html = fs.readFileSync(file, 'utf8');
function swap(a, b) { if (!html.includes(a)) throw new Error('Missing revision anchor: ' + a.slice(0, 80)); html = html.replace(a, b); }

const start = `<div class="start-content"><section class="panel start-card"><div class="panel-kicker">CURRENT SESSION</div><h2>Release review</h2><p>Session a4e91c20 · Active · Updated 2 minutes ago</p><div class="current-figures"><span><b>$0.42</b><small>Cost</small></span><span><b>18.2k</b><small>Tokens</small></span><span><b>18</b><small>Messages</small></span></div><button id="resumeCurrent"><span data-icon="play"></span> Resume current</button></section><section class="panel recent-panel"><div class="panel-kicker">RECENT SESSIONS</div><h2>Return to your work</h2><div class="session-grid"><button class="session-card" data-session="API migration"><span class="topline"><span class="monogram">C</span><strong>API migration</strong></span><span class="age-bars"><i></i><i></i><i></i><i></i><i></i><i></i></span><span class="session-meta">Updated 3 hr ago · 42 messages · 51k tokens</span><span class="session-flag">Active · Build phase · Command Center</span></button><button class="session-card" data-session="Docs audit"><span class="topline"><span class="monogram">O</span><strong>Docs audit</strong></span><span class="age-bars"><i></i><i></i><i></i><i></i><i></i><i></i></span><span class="session-meta">Updated yesterday · 9 messages · 7.4k tokens</span><span class="session-flag">History unavailable</span></button><button class="session-card" data-session="Security pass"><span class="topline"><span class="monogram">G</span><strong>Security pass</strong></span><span class="age-bars"><i></i><i></i><i></i><i></i><i></i><i></i></span><span class="session-meta">Updated 4 days ago · 24 messages · 21k tokens</span></button></div><div class="history-unavailable" id="sessionListError" hidden>Session list failed. <button id="retrySessionList">Retry session list</button></div></section></div>`;
html = html.replace(/<div class="start-content">[\s\S]*?<\/section><\/div><\/section><main class="deck"/, start + '</section><main class="deck"');
swap('SESSION CC-2048', 'SESSION a4e91c20');
swap("'SESSION CC-'+String(2048+session-1)", "'SESSION '+(session===1?'a4e91c20':'new')");
swap("$('startView').classList.toggle('show',s==='start');$('deck').classList.toggle('start-hidden',s==='start');", "$('startView').classList.toggle('show',s==='start'||s==='start-error');$('deck').classList.toggle('start-hidden',s==='start'||s==='start-error');$('sessionListError').hidden=s!=='start-error';");
swap('<option value="start">Preview state: Start view</option>', '<option value="start">Preview state: Start view</option><option value="start-error">Start list error</option>');
swap("$('allSessions').onclick=()=>showToast('Showing all recorded sessions.');", "$('allSessions').onclick=()=>showToast('Showing all sessions.');$('retrySessionList').onclick=()=>scenario('start');");
swap("return{id,name,vendor,status,angle,palette,kind,icon,desc,providerId:providerId||vendor.toLowerCase()}", "let idForProvider=providerId||vendor.toLowerCase();if(kind==='lane'&&!providerSlugs[idForProvider])vendor=idForProvider;return{id,name,vendor,status,angle,palette,kind,icon,desc,providerId:idForProvider}");

// This plate is driven by the same projection fields as the live detail card.
const detailStart = html.indexOf("function select(id){");
const detailEnd = html.indexOf("\nfunction makeLabels", detailStart);
if (detailStart < 0 || detailEnd < 0) throw new Error('Detail function missing');
html = html.slice(0, detailStart) + `function select(id){selected=id;let n=id==='ptah'?root:nodes.find(x=>x.id===id)||root;let status=n.id==='ptah'?(preview==='question'?'awaiting':voice):n.status;let provider=n.kind==='root'?'':n.vendor;let summary=n.desc||'';let detail=provider?'Provider: '+provider+'<br>Task: '+summary:summary; if(n.kind==='tribunal')detail+=' <br>Phase: '+(n.status==='completed'?'Synthesis complete':n.status==='failed'?'Synthesis failed':'Build / review');$('detail').innerHTML='<div class="panel-kicker">SELECTED · '+(n.kind==='root'?'ORCHESTRATOR':n.kind==='tribunal'?'TRIBUNAL GROUP':n.kind==='lane'?'CLI LANE':'CHILD SESSION')+'</div><h2>'+n.name+'</h2><p>'+summary+'</p><span class="detail-status" style="color:'+statusColor(status)+'">'+glyph(status)+' &nbsp;'+status+'</span><div class="detail-info">'+detail+'</div>';document.querySelectorAll('.work-row').forEach(e=>e.classList.toggle('current',e.dataset.select===id));labels.forEach(e=>e.classList.toggle('selected',e.dataset.id===id));refresh()}` + html.slice(detailEnd);

const projectionStart = html.indexOf('function projected(n,i,total){');
const projectionEnd = html.indexOf('\nfunction bez(', projectionStart);
if (projectionStart < 0 || projectionEnd < 0) throw new Error('Projection function missing');
html = html.slice(0, projectionStart) + `function sceneBounds(){let top=W<600?174:W<850?144:104,bottom=H-62;return{top,bottom,cy:(top+bottom)/2,room:(bottom-top)/2}}
function projected(n,i,total){let b=sceneBounds();if(n.id==='ptah')return{x:W*.5,y:b.cy,scale:W<600?.74:W<850?.84:1,depth:1};let dense=total>12,inner=dense&&i<8,a=n.angle+(reduced?0:Math.sin(time*.00012+i)*.018),sin=Math.sin(a);let rx=Math.min((dense?(inner?.235:.425):.405)*W,Math.max(42,W/2-48));let ry=Math.min((dense?(inner?.225:.385):.365)*(b.bottom-b.top),Math.max(28,b.room-(dense?34:48)));ry*=1+tilt*.007;let x=W*.5+Math.cos(a)*rx,y=b.cy+sin*ry;return{x,y,scale:dense?(inner?.72:.78):.76+.3*((sin+1)/2),depth:sin}}` + html.slice(projectionEnd);
swap('let cx=W*.5,cy=H*.485;', 'let cx=W*.5,cy=sceneBounds().cy;');
swap('H*(j===0?.385:j===1?.225:.365)', '(sceneBounds().bottom-sceneBounds().top)*(j===0?.385:j===1?.225:.365)');
swap('Math.max(66,Math.min(H-eh-42,yy))', 'Math.max(sceneBounds().top-8,Math.min(H-eh-42,yy))');

const css = `
/* Revision 1: reserved stage header band and responsive dock. */
.stage-head{position:absolute;left:0;right:0;top:0;height:104px;box-sizing:border-box;padding:18px 22px;display:flex;align-items:flex-start;background:linear-gradient(var(--stage),color-mix(in srgb,var(--stage) 97%,transparent));border-bottom:1px solid var(--border);z-index:7}
.stats{position:static;min-width:0;width:min(430px,48%);margin-left:auto}.stat{background:var(--panel)}
.stage-foot{z-index:7}.node-label,.overflow-chip{background:var(--panel);backdrop-filter:none}.node-label .meta,.node-label .plate-context,.session-meta,.stat-label,.detail-info,.work-row .row-sub,.count{color:var(--text)}
.rail{max-height:none}.work{flex:0 1 auto;max-height:330px;min-height:105px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:var(--gold) var(--panel)}.work-top{align-items:flex-start}.work-top h3{font-size:12px}.work-top .count{white-space:nowrap;flex:none;font-size:10px}.work:has(.work-row) h3:after{content:'SCROLL LIST ↓';display:block;margin-top:5px;color:var(--text);font:9px 'JetBrains Mono',monospace}.work:not(:has(.work-row)) h3:after{display:none}
.current-figures{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:28px 0 4px}.current-figures span{padding:10px;border:1px solid var(--border);border-radius:8px;background:var(--stage)}.current-figures b,.current-figures small{display:block}.current-figures b{font-size:14px}.current-figures small{margin-top:4px;color:var(--text);font:10px 'JetBrains Mono',monospace}
.history-unavailable[hidden]{display:none}.history-unavailable button{margin:0 0 0 8px}.session-card .session-flag{color:var(--text)}.session-card .session-meta{font-size:10px}
.approve{background:var(--gold);color:#17130c}html[data-theme=light] .approve{background:var(--gold);color:#fff}html[data-theme=light] .eyebrow,html[data-theme=light] .panel-kicker,html[data-theme=light] .stage-title,html[data-theme=light] .session-flag,html[data-theme=light] .node-label svg{color:oklch(50% 0.12 72)}
.top h1{white-space:nowrap}.top select,.top #demoBtn{display:none!important}
@media(max-width:1100px){.top{flex-wrap:wrap}.brand{min-width:0}.top-actions{width:100%;justify-content:flex-start;margin:0}.top .pill.session-pill{display:inline-flex}.stage-head{height:144px;display:block}.stats{width:100%;margin:12px 0 0}.stage{height:570px;min-height:570px}.dock{display:grid;grid-template-columns:56px minmax(55px,1fr) repeat(4,max-content);gap:7px;align-items:center}.dock .voice-disc{grid-row:1;grid-column:1}.dock .voice-name{grid-row:1;grid-column:2/7;min-width:0}.dock .wave{grid-row:2;grid-column:1/3}.dock .speaker{grid-row:2;grid-column:3}.dock #muteBtn{grid-row:2;grid-column:4}.dock #stopBtn{grid-row:2;grid-column:5}.dock #statusBtn{grid-row:2;grid-column:6}.dock #sessionBtn{grid-row:2;grid-column:7;white-space:nowrap}.dock .command{grid-row:3;grid-column:1/-1;width:100%;min-width:0;box-sizing:border-box}.dock .command input{min-width:0}}
@media(max-width:720px){.deck{grid-template-columns:1fr}.rail{display:flex;max-height:none}.stage{height:500px;min-height:500px}.dock{grid-template-columns:repeat(4,minmax(0,1fr))}.dock .voice-disc{grid-column:1}.dock .voice-name{grid-column:2/5}.dock .wave{grid-row:2;grid-column:1}.dock #muteBtn{grid-column:2}.dock #stopBtn{grid-column:3}.dock #statusBtn{grid-column:4}.dock .command{grid-row:3;grid-column:1/-1}.dock #sessionBtn{grid-row:4;grid-column:1/-1}.dock .speaker{display:none}.work{max-height:300px}.start-content{grid-template-columns:1fr}}
@media(max-width:480px){.top h1{font-size:17px}.top .context-pill{display:inline-flex}.stage{height:500px;min-height:500px}.stage-head{height:154px;padding:14px}.stats{grid-template-columns:repeat(2,1fr);margin-top:8px}.stat{padding:3px 6px}.stage-foot{left:14px;right:14px}.dock #muteBtn,.dock #stopBtn,.dock #statusBtn{padding:0 5px;font-size:11px}.current-figures{gap:3px}.current-figures span{padding:7px 3px}.start-actions{flex-wrap:wrap}}
`;
swap('</style>', css + '</style>');
fs.writeFileSync(file, html);
